package main
import ( "fmt"; "os"; "path/filepath"; "regexp"; "sort"; "strconv"; "strings"
	_ "github.com/paullepoulpe/jsgo/internal/diag"; "github.com/paullepoulpe/jsgo/internal/jscomp" )
type tuple struct{ line, col int; code string }
var re = regexp.MustCompile(`^(.+?):(\d+):(\d+): (?:ERROR|WARNING) - \[([A-Z_]+)\]`)
func parse(t string) []tuple { var o []tuple; for _,l := range strings.Split(t,"\n") { m:=re.FindStringSubmatch(l); if m!=nil { ln,_:=strconv.Atoi(m[2]); cl,_:=strconv.Atoi(m[3]); o=append(o,tuple{ln,cl,m[4]})}}; sort.Slice(o,func(i,j int)bool{if o[i].line!=o[j].line{return o[i].line<o[j].line}; return o[i].col<o[j].col}); return o }
func run(p string) []tuple { src,_:=os.ReadFile(p); d,_:=jscomp.CheckSource(p,string(src)); var o []tuple; for _,x:=range d { o=append(o,tuple{x.Line,x.Col,x.Code})}; sort.Slice(o,func(i,j int)bool{if o[i].line!=o[j].line{return o[i].line<o[j].line}; return o[i].col<o[j].col}); return o }
func codes(t []tuple) []string{s:=map[string]bool{}; for _,x:=range t{s[x.code]=true}; var o []string; for c:=range s{o=append(o,c)}; sort.Strings(o); return o}
func main(){ mode:="b"; filter:=""; if len(os.Args)>=2{mode=os.Args[1]}; if len(os.Args)>=3{filter=os.Args[2]}; var fs []string; filepath.Walk("testdata/fixtures/extracted",func(p string,i os.FileInfo,_ error)error{if !i.IsDir()&&strings.HasSuffix(p,".js"){fs=append(fs,p)}; return nil}); sort.Strings(fs); b:=map[string]int{}; s:=map[string][]string{}; p,f:=0,0; for _,fx:=range fs {o:="testdata/oracle"+strings.TrimSuffix(fx[len("testdata/fixtures"):],".js")+".txt"; bb,e:=os.ReadFile(o); if e!=nil{continue}; w:=parse(string(bb)); g:=run(fx); ok:=len(w)==len(g); if ok{for i:=range w{if w[i]!=g[i]{ok=false;break}}}; if ok{p++;continue}; f++; k:=fmt.Sprintf("want=%v got=%v",codes(w),codes(g)); if mode=="l"&&filter!=""&&k==filter{fmt.Println(fx)}; b[k]++; if len(s[k])<5{s[k]=append(s[k],fx)}}; if mode=="s"{fmt.Printf("pass=%d fail=%d rate=%.2f%%\n",p,f,100*float64(p)/float64(p+f));return}; type kv struct{K string;V int}; var sr []kv; for k,v:=range b{sr=append(sr,kv{k,v})}; sort.Slice(sr,func(i,j int)bool{return sr[i].V>sr[j].V}); for _,x:=range sr{if mode=="b"||x.K==filter{fmt.Printf("%4d %s\n",x.V,x.K); for _,e:=range s[x.K]{fmt.Printf("     %s\n",e)}}}; fmt.Printf("TOTAL p=%d f=%d\n",p,f) }
